/* АНАЛИЗ ДАННЫХ И ПРОГНОЗ: описательная статистика, корреляции, гистограмма, регрессия,
   t-тесты и дисперсионный анализ, прогноз ряда (Хольт — Винтерс, тренд, скользящее среднее,
   экспоненциальное сглаживание) с коридором и диаграммой.
   Где можно — пишем формулы листа (СРЗНАЧ, КОРРЕЛ, СЧЁТЕСЛИМН…): отчёт пересчитывается,
   когда меняются данные. Регрессию, проверки гипотез и прогноз считает код плагина
   (QR-разложение, распределения Стьюдента и Фишера) — их результат — числа. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const ЗАГ = {b: 1, fill: '#eef3fe', гр: РАМКА('тонкая', '#9aa4b5'), wrap: 1, valign: 'middle', align: 'center'};
const ЯЧ = {гр: РАМКА('тонкая', '#c5ccd8')};
const ИМЯ = {b: 1, fill: '#f6f8fb', гр: РАМКА('тонкая', '#c5ccd8')};
const НАЗВАНИЕ = {b: 1, size: 13, color: '#1f3b70'};
const ПОДЗАГ = {b: 1, color: '#1f3b70'};
const ЗАМЕТКА = {i: 1, color: '#5b6474'};
const ДЕНЬ = 86400000;
const ДМГ = д => { const x = new Date(Date.UTC(1899, 11, 30) + д * ДЕНЬ); return String(x.getUTCDate()).padStart(2, '0') + '.' + String(x.getUTCMonth() + 1).padStart(2, '0') + '.' + x.getUTCFullYear(); };
const ПИКС_СТОЛБЕЦ = 92, ПИКС_СТРОКА = 24;

class Отказ extends Error {}
const отказ = т => { throw new Отказ(т); };
const рус = (x, знаков = 4) => Number.isFinite(x) ? x.toLocaleString('ru-RU', {maximumFractionDigits: знаков}).replace(/ /g, ' ') : String(x);
const номерСтолбца = б => { let c = 0; for(const ch of б.toUpperCase()) c = c * 26 + ch.charCodeAt(0) - 64; return c - 1; };
function вЧисло(v){
  if(typeof v === 'number') return Number.isFinite(v) ? v : null;
  if(typeof v === 'boolean' || v == null) return null;
  const т = String(v).replace(/[\s ]/g, '').replace(',', '.');
  if(!/^[-+]?(\d+\.?\d*|\.\d+)(e[-+]?\d+)?%?$/i.test(т)) return null;
  const n = parseFloat(т); return т.endsWith('%') ? n / 100 : n;
}
const пусто = v => v === null || v === undefined || v === '';
const среднее = м => м.reduce((s, x) => s + x, 0) / м.length;
const дисперсия = м => { const ср = среднее(м); return м.reduce((s, x) => s + (x - ср) ** 2, 0) / (м.length - 1); };
/* формат по величине: деньги и тысячи — два знака, мелочь — больше */
function формат(образец){
  const м = Math.abs(образец);
  return !Number.isFinite(м) ? '0.00' : м >= 100 ? '#,##0.00' : м >= 1 ? '0.000' : м >= 0.001 || м === 0 ? '0.0000' : undefined;
}
/* совсем малые p — общим форматом: экспоненциальный формат клетки таблица пока показывает как 0,0000 */
const ФОРМАТ_P = p => p < 0.0001 ? undefined : '0.0000';
const pТекст = p => p < 0.0001 ? '< 0,0001' : '= ' + рус(p, 4);

/* ===== распределения: гамма, неполная бета, Стьюдент, Фишер, нормальное ===== */
function лнГамма(x){
  const к = [0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313, -176.61502916214059,
    12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
  if(x < 0.5) return Math.log(Math.PI / Math.abs(Math.sin(Math.PI * x))) - лнГамма(1 - x);
  x -= 1; let a = к[0]; const t = x + 7.5;
  for(let i = 1; i < 9; i++) a += к[i] / (x + i);
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}
function бетаДробь(a, b, x){
  const МАЛО = 1e-300; const qab = a + b, qap = a + 1, qam = a - 1;
  let c = 1, d = 1 - qab * x / qap; if(Math.abs(d) < МАЛО) d = МАЛО; d = 1 / d; let h = d;
  for(let m = 1; m <= 400; m++){
    const m2 = 2 * m;
    let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
    d = 1 + aa * d; if(Math.abs(d) < МАЛО) d = МАЛО; c = 1 + aa / c; if(Math.abs(c) < МАЛО) c = МАЛО; d = 1 / d; h *= d * c;
    aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2));
    d = 1 + aa * d; if(Math.abs(d) < МАЛО) d = МАЛО; c = 1 + aa / c; if(Math.abs(c) < МАЛО) c = МАЛО; d = 1 / d;
    const шаг = d * c; h *= шаг; if(Math.abs(шаг - 1) < 3e-16) break;
  }
  return h;
}
/* регуляризованная неполная бета I_x(a, b) */
function бета(a, b, x){
  if(x <= 0) return 0; if(x >= 1) return 1;
  const лн = лнГамма(a + b) - лнГамма(a) - лнГамма(b) + a * Math.log(x) + b * Math.log(1 - x);
  return x < (a + 1) / (a + b + 2) ? Math.exp(лн) * бетаДробь(a, b, x) / a : 1 - Math.exp(лн) * бетаДробь(b, a, 1 - x) / b;
}
const tДвусторонний = (t, df) => бета(df / 2, 0.5, df / (df + t * t));      /* P(|T| ≥ |t|) */
const tОдносторонний = (t, df) => tДвусторонний(t, df) / 2;
const fПравый = (f, d1, d2) => f <= 0 ? 1 : бета(d2 / 2, d1 / 2, d2 / (d2 + d1 * f));
function обратная(хвост, цель, верх){
  let lo = 0, hi = верх;
  for(let i = 0; i < 200 && hi - lo > 1e-13 * Math.max(1, lo); i++){ const m = (lo + hi) / 2; if(хвост(m) > цель) lo = m; else hi = m; }
  return (lo + hi) / 2;
}
const tКрит2 = (α, df) => обратная(t => tДвусторонний(t, df), α, 1e6);
const tКрит1 = (α, df) => обратная(t => tОдносторонний(t, df), α, 1e6);
const fКрит = (α, d1, d2) => обратная(f => fПравый(f, d1, d2), α, 1e8);
/* квантиль нормального распределения (П. Акклам) */
function нормОбр(p){
  const a = [-3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02, 1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00];
  const b = [-5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02, 6.680131188771972e+01, -1.328068155288572e+01];
  const c = [-7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00, -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00];
  const d = [7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00, 3.754408661907416e+00];
  const хв = q => (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
  if(p < 0.02425) return хв(Math.sqrt(-2 * Math.log(p)));
  if(p > 1 - 0.02425) return -хв(Math.sqrt(-2 * Math.log(1 - p)));
  const q = p - 0.5, r = q * q;
  return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q / (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1);
}

/* ===== данные: выделение со строкой заголовков ===== */
async function текущаяОбласть(имя, r, c){
  const R1 = Math.max(0, r - 300), C1 = Math.max(0, c - 40);
  const м = await лист(имя).прочитать(ОБЛАСТЬ(R1, C1, r + 3000, c + 40));
  const есть = (rr, cc) => { const ряд = м[rr - R1]; return !!ряд && !пусто(ряд[cc - C1]); };
  if(!есть(r, c)) return null;
  let r1 = r, r2 = r, c1 = c, c2 = c, рос = true;
  const строкаЕсть = (rr, a, b) => { for(let cc = a; cc <= b; cc++) if(есть(rr, cc)) return true; return false; };
  const столбецЕсть = (cc, a, b) => { for(let rr = a; rr <= b; rr++) if(есть(rr, cc)) return true; return false; };
  while(рос){
    рос = false;
    if(r1 > R1 && строкаЕсть(r1 - 1, c1, c2)){ r1--; рос = true; }
    if(r2 < r + 3000 && строкаЕсть(r2 + 1, c1, c2)){ r2++; рос = true; }
    if(c1 > C1 && столбецЕсть(c1 - 1, r1, r2)){ c1--; рос = true; }
    if(c2 < c + 40 && столбецЕсть(c2 + 1, r1, r2)){ c2++; рос = true; }
  }
  return {r1, c1, r2, c2};
}
async function данные(){
  const в = книга.выделение;
  if(!в || !в.область) отказ('Выделите данные вместе со строкой заголовков (или встаньте в таблицу).');
  let r1 = в.r1 - 1, c1 = в.c1 - 1, r2 = в.r2 - 1, c2 = в.c2 - 1;
  if(r1 === r2 && c1 === c2){
    const о = await текущаяОбласть(в.лист, r1, c1);
    if(!о) отказ('Клетка пуста. Выделите данные вместе со строкой заголовков.');
    ({r1, c1, r2, c2} = о);
  }
  if(c2 - c1 > 60) c2 = c1 + 60;
  r2 = Math.min(r2, r1 + 50000);
  const строки = await лист(в.лист).прочитать(ОБЛАСТЬ(r1, c1, r2, c2));
  let n = строки.length;
  while(n > 0 && !(строки[n - 1] || []).some(v => !пусто(v))) n--;
  if(n < 2) отказ('Данных слишком мало: выделите заголовки и хотя бы две строки чисел.');
  const первая = строки[0] || [];
  const естьШапка = первая.some(v => typeof v === 'string' && v.trim() !== '' && вЧисло(v) === null);
  const тело = строки.slice(естьШапка ? 1 : 0, n);
  const r0 = r1 + (естьШапка ? 1 : 0);
  const столбцы = [];
  for(let j = 0; j <= c2 - c1; j++){
    const имя = естьШапка && !пусто(первая[j]) ? String(первая[j]).trim() : 'Столбец ' + БУКВА(c1 + j);
    const сырые = тело.map(р => (р || [])[j]);
    const значения = сырые.map(вЧисло);
    const чисел = значения.filter(x => x !== null).length;
    столбцы.push({имя, c: c1 + j, сырые, значения, чисел, числовой: чисел > 0 && чисел >= сырые.filter(v => !пусто(v)).length * 0.8});
  }
  return {лист: в.лист, r0, r1, c1, r2: r0 + тело.length - 1, c2, строк: тело.length, столбцы, естьШапка};
}
/* столбец по заголовку или букве */
function найтиСтолбец(д, что, запасной){
  const т = String(что == null ? '' : что).trim();
  if(!т) return запасной;
  const поИмени = д.столбцы.find(x => x.имя.toLowerCase() === т.toLowerCase());
  if(поИмени) return поИмени;
  if(/^[A-Za-z]{1,3}$/.test(т)){ const c = номерСтолбца(т); const x = д.столбцы.find(x => x.c === c); if(x) return x; }
  отказ('В выделении нет столбца «' + т + '». Есть: ' + д.столбцы.map(x => x.имя).join(', ') + '.');
}
const числовые = д => д.столбцы.filter(x => x.числовой);
const кавычки = имя => /^[A-Za-zА-Яа-яЁё_][\wА-Яа-яЁё]*$/.test(имя) ? имя : "'" + имя.replace(/'/g, "''") + "'";
/* ссылка на столбец данных для формул на листе вывода */
function ссылка(д, ст, лВывода){
  const пр = лВывода === д.лист ? '' : кавычки(д.лист) + '!';
  return пр + '$' + БУКВА(ст.c) + '$' + (д.r0 + 1) + ':$' + БУКВА(ст.c) + '$' + (д.r2 + 1);
}

/* ===== куда выводить ===== */
const ПАМЯТЬ = 'анализ-занято';
function занятоДиаграммами(имя){ let м = []; try { м = лист(имя).память(ПАМЯТЬ) || []; } catch(e){} return Array.isArray(м) ? м : []; }
const пересекаются = (a, b) => a.r1 <= b.r2 && b.r1 <= a.r2 && a.c1 <= b.c2 && b.c1 <= a.c2;
async function место(д, высота, ширина){
  const п = параметры({});
  const к = String(п.куда || '').trim();
  if(к){
    const м = /^(?:'?([^'!]+)'?!)?\$?([A-Za-z]{1,3})\$?(\d+)$/.exec(к);
    if(!м) отказ('«Куда вывести» — адрес клетки, например H2 или Лист2!A1.');
    const имя = м[1] || д.лист;
    if(!книга.листы.includes(имя)) отказ('Нет листа «' + имя + '».');
    const r = +м[3] - 1, c = номерСтолбца(м[2]);
    const кус = await лист(имя).прочитать(ОБЛАСТЬ(r, c, r + высота - 1, c + ширина - 1));
    if(кус.some(р => (р || []).some(v => !пусто(v)))){
      const да = await диалог.вопрос('Область ' + имя + '!' + ОБЛАСТЬ(r, c, r + высота - 1, c + ширина - 1) + ' не пуста. Записать отчёт поверх?');
      if(!да) return null;
    }
    return {имя, r, c};
  }
  /* сами: правее данных, через один пустой столбец; не на чужие клетки и не под прежние диаграммы */
  const r = д.r1, c0 = д.c2 + 2;
  const кус = await лист(д.лист).прочитать(ОБЛАСТЬ(r, c0, r + высота - 1, c0 + ширина + 80));
  const занято = занятоДиаграммами(д.лист);
  for(let c = c0; c <= c0 + 80; c++){
    let чисто = true;
    /* правее первого места — ещё и пустой столбец слева, чтобы отчёты не слипались */
