/* ===== 2. Корреляции (формулы КОРРЕЛ, цвет — по силе связи) ===== */
function корр(a, b){
  const x = [], y = [];
  for(let i = 0; i < a.length; i++) if(a[i] !== null && b[i] !== null){ x.push(a[i]); y.push(b[i]); }
  if(x.length < 3) return NaN;
  const мx = среднее(x), мy = среднее(y); let sxy = 0, sxx = 0, syy = 0;
  for(let i = 0; i < x.length; i++){ sxy += (x[i] - мx) * (y[i] - мy); sxx += (x[i] - мx) ** 2; syy += (y[i] - мy) ** 2; }
  return sxy / Math.sqrt(sxx * syy);
}
function цветКорр(r){
  if(!Number.isFinite(r)) return '#ffffff';
  const к = Math.min(1, Math.abs(r)), [R, G, B] = r >= 0 ? [91, 141, 239] : [232, 96, 76];
  const м = (ц, w) => Math.round(255 + (ц - 255) * w * 0.75).toString(16).padStart(2, '0');
  return '#' + м(R, к) + м(G, к) + м(B, к);
}
