/* ===== 3. Гистограмма (формулы СЧЁТЕСЛИМН) ===== */
function красивыйШаг(x){
  const п = Math.pow(10, Math.floor(Math.log10(x))), д = x / п;
  return (д <= 1 ? 1 : д <= 2 ? 2 : д <= 2.5 ? 2.5 : д <= 5 ? 5 : 10) * п;
}
