/* ===== 4. Регрессия: МНК через QR-разложение (Хаусхолдер) ===== */
function мнк(X, y){
  const n = X.length, k = X[0].length;
  const A = X.map(р => р.slice()), b = y.slice();
  for(let j = 0; j < k; j++){
    let н = 0; for(let i = j; i < n; i++) н += A[i][j] * A[i][j]; н = Math.sqrt(н);
    if(н === 0) continue;
    const α = A[j][j] > 0 ? -н : н;
    const v = new Array(n).fill(0); v[j] = A[j][j] - α; for(let i = j + 1; i < n; i++) v[i] = A[i][j];
    let vv = 0; for(let i = j; i < n; i++) vv += v[i] * v[i];
    if(vv === 0) continue;
    for(let c = j; c < k; c++){ let s = 0; for(let i = j; i < n; i++) s += v[i] * A[i][c]; s = 2 * s / vv; for(let i = j; i < n; i++) A[i][c] -= s * v[i]; }
    let s = 0; for(let i = j; i < n; i++) s += v[i] * b[i]; s = 2 * s / vv; for(let i = j; i < n; i++) b[i] -= s * v[i];
  }
  let макс = 0; for(let i = 0; i < k; i++) макс = Math.max(макс, Math.abs(A[i][i]));
  for(let i = 0; i < k; i++) if(!(Math.abs(A[i][i]) > 1e-10 * макс)) return {вырождено: i};
  const β = new Array(k);
  for(let i = k - 1; i >= 0; i--){ let s = b[i]; for(let c = i + 1; c < k; c++) s -= A[i][c] * β[c]; β[i] = s / A[i][i]; }
  const Ri = Array.from({length: k}, () => new Array(k).fill(0));
  for(let i = k - 1; i >= 0; i--){
    Ri[i][i] = 1 / A[i][i];
    for(let j = i + 1; j < k; j++){ let s = 0; for(let m = i + 1; m <= j; m++) s += A[i][m] * Ri[m][j]; Ri[i][j] = -s / A[i][i]; }
  }
  return {β, диаг: Ri.map(р => р.reduce((s, x) => s + x * x, 0))};
}
function регрессияСчёт(y, Xs){
  const n = y.length, p = Xs.length;
  const X = y.map((_, i) => [1, ...Xs.map(x => x[i])]);
  const р = мнк(X, y);
  if(р.вырождено !== undefined) return р;
  const ŷ = X.map(ряд => ряд.reduce((s, x, j) => s + x * р.β[j], 0));
  const ср = среднее(y);
  const SST = y.reduce((s, v) => s + (v - ср) ** 2, 0);
  const SSE = y.reduce((s, v, i) => s + (v - ŷ[i]) ** 2, 0);
  const SSR = SST - SSE, dfR = p, dfE = n - p - 1;
