  const R2 = SST > 0 ? SSR / SST : 0;
  const F = (SSR / dfR) / MSE;
  const ош = р.диаг.map(d => se * Math.sqrt(d));
  const t = р.β.map((b, j) => b / ош[j]);
  return {n, p, β: р.β, ош, t, pЗнач: t.map(x => tДвусторонний(Math.abs(x), dfE)), ŷ, остатки: y.map((v, i) => v - ŷ[i]),
