/* ===== 6. Прогноз ===== */
/* Хольт — Винтерс, аддитивная модель (ETS A,A,A в записи Хайндмана):
   уровень  L = α(y − S[t−m]) + (1−α)(L + T)
   тренд    T = β(L_новый − L) + (1−β)T
   сезон    S[t] = γ(y − L_прежний − T_прежний) + (1−γ)S[t−m],   0 ≤ γ ≤ 1 − α */
function хв(y, m, α, β, γ){
  const n = y.length;
  let L, T, S = new Array(n).fill(0), старт;
  if(m > 1){
    const с1 = среднее(y.slice(0, m)), с2 = среднее(y.slice(m, 2 * m));
    L = с1; T = (с2 - с1) / m; for(let i = 0; i < m; i++) S[i] = y[i] - с1;
    L = с1 + T * (m - 1) / 2;              /* уровень — в конце первого сезона */
    старт = m;
  } else { L = y[0]; T = y[1] - y[0]; старт = 1; }
  const модель = new Array(n).fill(null);
  let SSE = 0, ок = 0;
  for(let t = старт; t < n; t++){
    const s = m > 1 ? S[t - m] : 0;
    const прогн = L + T + s; модель[t] = прогн;
    const e = y[t] - прогн; SSE += e * e; ок++;
    const Lн = α * (y[t] - s) + (1 - α) * (L + T);
    const Tн = β * (Lн - L) + (1 - β) * T;
    if(m > 1) S[t] = γ * (y[t] - L - T) + (1 - γ) * s;
    L = Lн; T = Tн;
  }
  return {L, T, S, модель, SSE, ок};
}
function прогнозХВ(ф, n, m, h){ const out = []; for(let k = 1; k <= h; k++) out.push(ф.L + k * ф.T + (m > 1 ? ф.S[n - m + ((k - 1) % m)] : 0)); return out; }
/* Нелдер — Мид в кубе (0,1)^d через логиты */
function подобрать(цель, d){
  const σ = x => 1 / (1 + Math.exp(-x)), f = z => цель(z.map(σ));
  let лучшее = null;
  const сетка = d === 3 ? [[-1, -3, -2], [0.5, -2, -1], [-2, -4, -3], [1.5, -1, 0], [0, -3, -1]] : d === 2 ? [[-1, -3], [0.5, -2], [-2, -4], [1.5, -1]] : [[-2], [0], [2]];
  for(const старт of сетка){
    let pts = [старт.slice()]; for(let i = 0; i < d; i++){ const p = старт.slice(); p[i] += 1; pts.push(p); }
    let зн = pts.map(f);
    for(let it = 0; it < 300 * d; it++){
      const пор = зн.map((v, i) => i).sort((a, b) => зн[a] - зн[b]); pts = пор.map(i => pts[i]); зн = пор.map(i => зн[i]);
      if(Math.abs(зн[d] - зн[0]) < 1e-10 * (1 + Math.abs(зн[0]))) break;
      const ц = new Array(d).fill(0); for(let i = 0; i < d; i++) for(let j = 0; j < d; j++) ц[j] += pts[i][j] / d;
      const отр = ц.map((c, j) => c + (c - pts[d][j])), fo = f(отр);
      if(fo < зн[0]){ const раст = ц.map((c, j) => c + 2 * (c - pts[d][j])), fr = f(раст); if(fr < fo){ pts[d] = раст; зн[d] = fr; } else { pts[d] = отр; зн[d] = fo; } }
      else if(fo < зн[d - 1]){ pts[d] = отр; зн[d] = fo; }
      else { const сж = ц.map((c, j) => c + 0.5 * (pts[d][j] - c)), fc = f(сж);
        if(fc < зн[d]){ pts[d] = сж; зн[d] = fc; }
        else for(let i = 1; i <= d; i++){ pts[i] = pts[i].map((x, j) => pts[0][j] + 0.5 * (x - pts[0][j])); зн[i] = f(pts[i]); } }
    }
    const лучший = зн.indexOf(Math.min(...зн));
    if(!лучшее || зн[лучший] < лучшее.v) лучшее = {v: зн[лучший], x: pts[лучший].map(σ)};
  }
  return лучшее.x;
}
function автокорр(y, лаг){
  const n = y.length, t̄ = (n - 1) / 2, ср = среднее(y);
  let sxy = 0, sxx = 0; y.forEach((v, i) => { sxy += (i - t̄) * (v - ср); sxx += (i - t̄) ** 2; });
  const b = sxy / sxx, z = y.map((v, i) => v - ср - b * (i - t̄));
  const з = z.reduce((s, x) => s + x * x, 0); if(!з) return 0;
  let s = 0; for(let i = лаг; i < n; i++) s += z[i] * z[i - лаг];
  return s / з;
}
function найтиСезон(y){
  const кандидаты = [12, 4, 7, 52, 24, 6, 5, 3].filter(m => y.length >= 2 * m + 2);
  let лучший = 0, ак = 0.3;
  for(const m of кандидаты){ const a = автокорр(y, m); if(a > ак + 0.05){ лучший = m; ак = a; } }
  return лучший;
}
/* подписи будущих периодов: числа с шагом, даты помесячно или с шагом в днях, «Неделя 12» → «Неделя 13» */
function продолжитьПодписи(подписи, h, заголовок){
  const n = подписи.length;
  const чис = подписи.map(v => typeof v === 'number' ? v : null);
  if(n >= 2 && чис.every(v => v !== null)){
    const шаги = чис.slice(1).map((v, i) => v - чис[i]);
    const похожеДаты = чис.every(v => v > 25569 && v < 73051) && (/дат|месяц|день|недел|период|квартал/i.test(заголовок) || шаги.every(s => s >= 28 && s <= 31));
    if(похожеДаты && шаги.every(s => s >= 28 && s <= 31)){
      const д = new Date(Date.UTC(1899, 11, 30) + чис[n - 1] * ДЕНЬ), день = new Date(Date.UTC(1899, 11, 30) + чис[0] * ДЕНЬ).getUTCDate();
      const out = [];
      for(let k = 1; k <= h; k++){
        const г = д.getUTCFullYear(), м = д.getUTCMonth() + k;
        const дней = new Date(Date.UTC(г, м + 1, 0)).getUTCDate();
        out.push(Math.round((Date.UTC(г, м, Math.min(день, дней)) - Date.UTC(1899, 11, 30)) / ДЕНЬ));
      }
      return {значения: out, дата: true};
    }
    const шаг = шаги[шаги.length - 1];
    if(шаги.every(s => Math.abs(s - шаг) < 1e-9 * Math.max(1, Math.abs(шаг))) || похожеДаты)
      return {значения: Array.from({length: h}, (_, k) => +(чис[n - 1] + (k + 1) * шаг).toPrecision(12)), дата: похожеДаты};
  }
